#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    DailyMissionGoal, DAILY_MISSION_GOALS, DAILY_MISSION_GOALS_BY_INDEX
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * Emit the goal a daily mission asks for at each of its tiers.
 *
 * `DAILY_MISSION_TIER_REWARDS` has always described what a mission PAYS. What it asks —
 * "kill 50 basic enemies", "advance through 30 waves" — was not in this package at all,
 * because the numbers are not on the mission struct. They live in static array initializers
 * that `Cards`-style extraction could not reach until tower-extractor learned to resolve
 * `RuntimeHelpers.InitializeArray`, so the goal arrays read back as correctly-sized runs of
 * zeros: present, plausible, and empty.
 *
 * Reads `facts/<version>/daily-mission-goals.json`, which carries game data only. The
 * evidence for those values — which method builds them, how it was run, what was verified —
 * stays in tower-extractor, where it can be re-derived and where a guard already checks it.
 * A consumer of this package needs the numbers and their units, not the archaeology.
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const here = path.dirname(fileURLToPath(import.meta.url))
const root = path.resolve(here, '..')
const VERSION = 'v29.0.0'
const factPath = path.join(root, 'facts', VERSION, 'daily-mission-goals.json')
const outPath = path.join(root, 'src', 'data', 'generated', 'daily-mission-goals.generated.ts')

if (!fs.existsSync(factPath)) {
  console.error(`missing ${path.relative(root, factPath)}`)
  console.error('  Written by tower-extractor: python scripts/export-sdk-facts.py --out <here>')
  process.exit(1)
}

const fact = JSON.parse(fs.readFileSync(factPath, 'utf8'))
const missions = fact.missions ?? []

// A mission with no goals at all would mean the extraction regressed to the zero-filled
// state this file exists to replace. Refuse rather than emit a table of empties.
const empty = missions.filter(m => !m.goalValues?.length)
if (empty.length) {
  console.error(`${empty.length} mission(s) have no goal values: ${empty.map(m => m.index).join(', ')}`)
  console.error('  That is the shape the InitializeArray stub used to produce. Not emitting.')
  process.exit(1)
}

const rows = missions
  .map(m => {
    const text = JSON.stringify(m.text ?? '')
    const type = JSON.stringify(m.missionType ?? '')
    const goals = m.goalValues.map(v => (Number.isInteger(v) ? v : Number(v.toFixed(4)))).join(', ')
    return `  { index: ${m.index}, missionType: ${type}, text: ${text}, goals: [${goals}] },`
  })
  .join('\n')

const source = `/**
 * GENERATED by \`scripts/build-daily-mission-goals.mjs\` from facts/${VERSION}. Do not edit.
 *
 * What each daily mission asks for, at each of its goal tiers, as the game's own code
 * computes it. \`text\` keeps its {0} placeholder: the game fills it with the goal for the
 * tier the player was given, and rendering one here would pick a tier arbitrarily.
 */
export interface DailyMissionGoal {
  /** The mission's index in the game's mission pool. */
  index: number
  /** Mission category, as the game names it. */
  missionType: string
  /** Mission text, with its {0} placeholder intact. */
  text: string
  /** The goal at each tier, in tier order. */
  goals: readonly number[]
}

export const DAILY_MISSION_GOALS: readonly DailyMissionGoal[] = [
${rows}
] as const

export const DAILY_MISSION_GOALS_BY_INDEX: ReadonlyMap<number, DailyMissionGoal> = new Map(
  DAILY_MISSION_GOALS.map(mission => [mission.index, mission]),
)
`

fs.writeFileSync(outPath, source)
console.log(`  wrote ${path.relative(root, outPath)}  (${missions.length} missions)`)
